for (const [prog, expected] of CASES) {
  test('B7 decimal: ' + prog.split('\n')[0].slice(0, 60), async () => {
    const r = await run(PREFIX + prog);
    assert.deepEqual(errs(r), []);
    assert.deepEqual(outs(r), expected);
  });
}

const ERROR_CASES = [
  ["print(Decimal('0') ** 0)", "InvalidOperation"],
  ["print(Decimal('Infinity') / Decimal('Infinity'))", "InvalidOperation"],
  ["print(Decimal('NaN') < 1, Decimal('NaN') == Decimal('NaN'), Decimal('NaN') != 1)", "InvalidOperation"],
  ["setcontext(Context(prec=3, rounding=ROUND_CEILING))\nprint(Decimal('50768e17').quantize(Decimal('0.001')))\nprint(Decimal('50768e17') + Decimal('18894754643324724e11'))", "InvalidOperation"],
  ["setcontext(Context(prec=1, rounding=ROUND_HALF_UP))\nprint(Decimal('59e7').quantize(Decimal('0.001')))\nprint(Decimal('59e7') + Decimal('1e-19'))", "InvalidOperation"],
];
for (const [prog, kind] of ERROR_CASES) {
  test('B7 decimal error: ' + prog.split('\n')[0].slice(0, 60), async () => {
    const r = await run(PREFIX + prog);
    assert.ok(errs(r).some((m) => m.includes(kind)), errs(r).join(' / '));
  });
}

